///////////////////////////////////////////////////////////////
// Hopf + Poincaré + Reflection/Refraction + Loxodromic Test //
// Author: YourName
///////////////////////////////////////////////////////////////
#ifdef GL_ES
precision mediump float;
#endif


// We'll let you pick which method (1..5)
uniform int   uMode; 

// Refractive index for glass
const float refractiveIndex = 1.5;
const float PI = 3.14159265359;

//----------------------------------------
// 1) Hopf map (S^3 -> S^2)
//----------------------------------------
vec3 hopfMap(vec3 p)
{
    // Same as your original code, but let's rename
    // to avoid confusion. Suppose p is actually (x,y,z) in R^3
    // on an embedded S^3 approach. If you want the quaternion approach,
    // you’ll need a vec4. But let's keep it at a simplified 3D for example:
    float lenSq = dot(p, p);
    vec4 q = vec4(2.0*p, lenSq - 1.0)/(lenSq + 1.0);

    float X = 2.0*(q.x*q.z + q.y*q.w);
    float Y = 2.0*(q.y*q.z - q.x*q.w);
    float Z = q.w*q.w + q.z*q.z - q.x*q.x - q.y*q.y;
    return vec3(X, Y, Z);
}

//----------------------------------------
// 2) Poincaré disk mapping (S^2 -> Disk)
//----------------------------------------
vec2 poincareDisk(vec2 uv)
{
    // same as original
    float r = length(uv);
    float theta = atan(uv.y, uv.x);
    float s = tanh(r);
    return s * vec2(cos(theta), sin(theta));
}
vec2 toDisk(vec3 s2)
{
    // or a direct stereographic from S^2
    float denom = 1.0 + s2.z;
    return (denom > 1e-7) ? (s2.xy / denom) : vec2(0.0);
}
vec3 fromDisk(vec2 d)
{
    float r2 = dot(d,d);
    float denom = 1.0 + r2;
    float x = 2.0*d.x/denom;
    float y = 2.0*d.y/denom;
    float z = (r2 - 1.0)/denom;
    return vec3(x,y,z);
}

//----------------------------------------
// 3) Reflection/Refraction from original
//----------------------------------------
vec3 refractRay(vec3 I, vec3 N, float eta) {
    float cosi = clamp(dot(-I, N), -1.0, 1.0);
    float k = 1.0 - eta*eta*(1.0 - cosi*cosi);
    return (k<0.0) ? vec3(0.0) : eta*I + (eta*cosi - sqrt(k))*N;
}
vec3 reflectRay(vec3 I, vec3 N) {
    return I - 2.0*dot(I,N)*N;
}

//----------------------------------------
// 4) Loxodromic transforms on the disk
//    We'll define 5 examples
//----------------------------------------

// Generic helper: complex multiply
vec2 cMul(vec2 a, vec2 b){
    return vec2(a.x*b.x - a.y*b.y, a.x*b.y + a.y*b.x);
}

// 4A) Basic “z -> scale * rotate * (z - a)/(1 - conj(a)*z)” approach
vec2 loxodromicA(vec2 z, float time)
{
    float scale  = 1.02 + 0.01*sin(2.0*time);
    float angle  = 0.4*time; 
    vec2  a      = vec2(0.2, 0.0); // shift anchor
    // complex rotation
    vec2 rotation = vec2(cos(angle), sin(angle));
    // denominator = 1 - conj(a)*z => conj(a) = (a.x, -a.y)
    float den = 1.0 - (a.x*z.x + -a.y*z.y);
    if(abs(den)<1e-6) den = 1e-6;
    vec2 num = vec2(z.x - a.x, z.y - a.y);
    // scale + rotate factor
    vec2 lr = scale*cMul(rotation, num/den);
    return lr;
}

// 4B) Loxodromic with an exponential twist factor
//     “z -> e^(alpha + i beta) * z”
vec2 loxodromicB(vec2 z, float time)
{
    // alpha controls radial scale, beta controls rotation
    float alpha = 0.01*sin(1.3*time);
    float beta  = 0.3 + 0.1*cos(time);
    // e^(alpha + i beta) = e^alpha * (cos beta + i sin beta)
    float ealpha   = exp(alpha);
    vec2  rot      = vec2(cos(beta), sin(beta));
    // multiply
    return ealpha * cMul(rot, z);
}

// 4C) A multi-iteration “Cayley transform” style approach
vec2 loxodromicC(vec2 z, float time)
{
    // example: do two mini-lifts in one step
    // z -> (z - i)/(z + i), but i is a time-shifted imaginary
    // We'll define "i" as (0,1)
    vec2 iImag = vec2(0.0, 1.0*sin(time));
    // first transform
    vec2 top   = z - iImag;
    vec2 bot   = z + iImag;
    float den  = dot(bot, bot); // bot.x^2 + bot.y^2
    if(den<1e-6) den=1e-6;
    vec2 step1 = vec2(
       (top.x*bot.x + top.y*bot.y),
       (top.y*bot.x - top.x*bot.y)
    ) / den;
    // do it again
    vec2 step2 = (step1 - iImag)/(step1 + iImag);
    return step2;
}

// 4D) A time-limited swirl + shift
vec2 loxodromicD(vec2 z, float time)
{
    float swirl = 0.5 + 0.5*sin(time);
    float scale = 1.01 + 0.01*cos(3.0*time);
    // rotate
    float a = swirl;
    vec2 rot = vec2(cos(a), sin(a));
    vec2 zOut = scale*cMul(rot,z) + 0.1*vec2(sin(2.0*time),cos(2.0*time));
    return zOut;
}

// 4E) A random-like iteration of multiple Möbius transforms
vec2 loxodromicE(vec2 z, float time)
{
    // We'll pick from 2 random "seeds" based on time
    float seed = floor(mod(time*0.5, 2.0));
    if(seed<1.0){
        // transform 1
        // z->(z-0.2)/(1-0.2z)
        float den=1.0 - 0.2*z.x; // ignoring y for simplicity
        if(abs(den)<1e-6) den=1e-6;
        return (z - vec2(0.2,0.0))/den;
    } else {
        // transform 2
        // z->(z+0.2i)/(1+0.2i z)
        vec2 i2 = vec2(0.0, 0.2);
        float den = dot(vec2(1.0,0.0)+ cMul(i2,z), vec2(1.0,0.0)+ cMul(i2,z));
        den = max(den,1e-6);
        vec2 top = z + i2;
        return top / den; // simplified
    }
}

//----------------------------------------
// 5) Select one of the 5 loxodromic transforms
//----------------------------------------
vec2 applyLoxodromic(vec2 z, float time, int mode)
{
    if(mode==1) return loxodromicA(z, time);
    else if(mode==2) return loxodromicB(z, time);
    else if(mode==3) return loxodromicC(z, time);
    else if(mode==4) return loxodromicD(z, time);
    else             return loxodromicE(z, time);
}

//----------------------------------------
// 6) Rotation helpers
//----------------------------------------
mat3 rotationY(float angle){
    float s=sin(angle), c=cos(angle);
    return mat3(
       c,  0, s,
       0,  1, 0,
      -s,  0, c
    );
}
mat3 rotationX(float angle){
    float s=sin(angle), c=cos(angle);
    return mat3(
       1, 0,  0,
       0, c, -s,
       0, s,  c
    );
}

//----------------------------------------
// 7) Main Shading
//----------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalize pixel coords to [-1,1]
    vec2 uv = (fragCoord*2.0 - iResolution.xy)/iResolution.y;

    // Time variable
    float t = iTime*0.5;

    // Poincaré disk mapping
    // We'll treat uv as if it's just a planar input
    vec2 diskUV = poincareDisk(uv);

    // Build a point p in R^3, but let's do a simpler approach
    // from earlier code:
    vec3 p;
    p.x = sin(t)*diskUV.x;
    p.y = sin(t)*diskUV.y;
    p.z = cos(t)*length(diskUV);

    // Apply rotations
    mat3 rotY = rotationY(t);
    mat3 rotX = rotationX(t*0.5);
    p = rotY*rotX*p;

    // For fractal iteration, do several loops:
    const int ITER = 5;
    for(int i=0; i<ITER; i++){
       // Hopf to S^2
       vec3 s2 = hopfMap(p);

       // S^2 -> Disk
       vec2 d = toDisk(normalize(s2));

       // Loxodromic transform
       vec2 d2 = applyLoxodromic(d, t+float(i)*0.3, uMode);

       // Disk -> S^2
       vec3 s2b = fromDisk(d2);

       // Now re-embed s2b into R^3 (approx 3-sphere if you'd prefer a 4D approach)
       // We'll just treat s2b as a new direction in R^3
       // Then combine with old radius or do a direct assignment
       float rr = length(p); 
       p = rr * normalize(s2b);

       // Optionally rotate again
       mat3 rX = rotationX(t*0.1 + float(i)*0.2);
       mat3 rY = rotationY(t*0.1 + float(i)*0.2);
       p = rY*rX*p;
    }

    // Now 'p' is the final direction after loxodromic recursion

    // Normal for reflection
    vec3 normal = normalize(p);

    // Light direction
    vec3 lightDir = normalize(vec3(0,0,1));

    // Reflection/refraction as in the original
    float eta       = 1.0/refractiveIndex;
    vec3 refracted  = refractRay(-lightDir, normal, eta);
    vec3 reflected  = reflectRay(-lightDir, normal);

    float cosi      = clamp(dot(-lightDir, normal), 0.0, 1.0);
    float fresnel   = mix(pow(1.0 - cosi,3.0),1.0,0.1);

    vec3 refrColor  = 0.5 + 0.5*refracted;
    vec3 reflColor  = 0.5 + 0.5*reflected;

    // Combine
    vec3 color = mix(refrColor, reflColor, fresnel);

    // Mask to the disk boundary in uv
    float mask = smoothstep(1.0, 0.99, length(uv));
    color *= mask;

    fragColor = vec4(color,1.0);
}
